#ifndef __MANIFEST_H__
#define __MANIFEST_H__

#include <stdbool.h>
#include <stddef.h>

/**
 * Sprite animations listed in assets/techride/manifest.txt (generated by
 * tools/extract_sheets.py). Each line:
 *   anim <id> <folder> <frames> <fps> <size> <anchor> <loop|once>
 * Frames are <folder>00.png, 01.png, ... under assets/techride/.
 */
#define MAX_ANIM_FRAMES 8
#define MAX_HULL_POINTS 16

typedef struct anim
{
  char id[48];
  char folder[160];
  size_t frames;
  double fps;
  bool loop;
  bool has_anchor; // head position for accessories (fractions of the frame)
  double head_x, head_top, height;
  // per-frame collision outline (convex, fractions of the frame, y down)
  unsigned char hull_count[MAX_ANIM_FRAMES];
  float hull[MAX_ANIM_FRAMES][MAX_HULL_POINTS][2];
} anim_t;

/**
 * @param id an animation id such as "techbot.run"
 * @return the animation, or NULL if the manifest doesn't have it
 */
const anim_t *anim_get(const char *id);

/**
 * @param anim an animation
 * @param time seconds since it started
 * @return the frame to show (looping animations wrap; others hold the last)
 */
size_t anim_frame_at(const anim_t *anim, double time);

/**
 * @param anim an animation
 * @return how long one pass of it takes, in seconds
 */
double anim_duration(const anim_t *anim);

/**
 * Like anim_frame_at, plus the next frame and how far to fade toward it.
 * Frames hold crisp for most of their time and fade only near the end.
 *
 * @param anim an animation
 * @param time seconds since it started
 * @param frame set to the current frame
 * @param next set to the next frame
 * @param fade set to the fade amount, 0 to 1
 */
void anim_blend_at(const anim_t *anim, double time, size_t *frame, size_t *next, double *fade);

/**
 * Asset path of one frame. The returned string is overwritten by the next call.
 *
 * @param anim an animation
 * @param frame the frame index
 * @return the frame's asset path
 */
const char *anim_frame_path(const anim_t *anim, size_t frame);

/**
 * The collision outline of one frame, if the manifest has one.
 *
 * @param anim an animation
 * @param frame the frame index
 * @param count set to the number of points (0 if none)
 * @return the points as (x, y) fractions of the frame, y down
 */
const float (*anim_hull(const anim_t *anim, size_t frame, size_t *count))[2];

#endif // #ifndef __MANIFEST_H__
